if not table.clear then function table.clear(t) for k in pairs(t) do t[k]=nil end end end
local function signal()
 local s={listeners={}}
 function s:Connect(fn)local c={live=true};self.listeners[#self.listeners+1]={c,fn};function c:Disconnect()c.live=false end;return c end
 function s:Fire(...)for _,v in ipairs(self.listeners)do if v[1].live then v[2](...)end end end
 return s
end
local methods={};local meta={__index=function(t,k)return methods[k]or t.props[k]end,__newindex=function(t,k,v)
 if k=="Parent"then local old=t.props.Parent;if old then for i,x in ipairs(old.children)do if x==t then table.remove(old.children,i);break end end;old.ChildRemoved:Fire(t)end;t.props.Parent=v;if v then v.children[#v.children+1]=t;v.ChildAdded:Fire(t);local a=v;while a do a.DescendantAdded:Fire(t);a=a.Parent end end
