local timers,clock={},0;task={delay=function(s,f)timers[#timers+1]={at=clock+s,fn=f}end,defer=function(f)f()end}
local function advance(s)local endAt=clock+s;while true do local pick;for i,t in ipairs(timers)do if t.at<=endAt and(not pick or t.at<pick.at)then pick={i=i,at=t.at,fn=t.fn}end end;if not pick then break end;table.remove(timers,pick.i);clock=pick.at;pick.fn()end;clock=endAt end
